-- 往返运费审核和结算追溯分别授权；已阅只记录查看事实。
ALTER TABLE admin_menu DROP CHECK ck_admin_menu_9, ADD CONSTRAINT ck_admin_menu_9 CHECK (permission_code IS NULL OR REGEXP_LIKE(permission_code, '^admin:[a-z0-9-]+:[a-z0-9-]+$','c') OR permission_code IN ('admin:trade:order:read','admin:trade:payment:read','admin:trade:refund:read','admin:trade:merchant:read','admin:trade:merchant:sync','admin:trade:transport:manage','admin:trade:operation:read','admin:fulfillment:return:read','admin:fulfillment:return:close','admin:fulfillment:risk:read','admin:fulfillment:expense:read','admin:fulfillment:expense:review'));
